using System;using System.IO;using System.Linq;using System.Management;using System.Runtime.InteropServices;using System.ComponentModel;using System.Collections.Generic;using System.Text;using Microsoft.Win32.SafeHandles;
namespace FileCompass {
 public sealed class ExtSource {public string Device,Name,Token;public bool Physical,Removable;public long Length;public int Sector=512;public override string ToString(){return Name;}}
 internal sealed class ExtDiskStream:Stream {
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle CreateFile(string name,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool DeviceIoControl(SafeFileHandle h,uint code,byte[] input,int inputSize,byte[] output,int outputSize,out int returned,IntPtr overlapped);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool SetFilePointerEx(SafeFileHandle h,long offset,out long result,uint origin);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool ReadFile(SafeFileHandle h,byte[] data,int size,out int count,IntPtr overlapped);
  SafeFileHandle handle;long position,length;int sector;byte[] cache;long cacheStart=-1;int cached;internal int Sector{get{return sector;}}
  static byte[] Query(SafeFileHandle h,uint code,byte[] input,int size){var data=new byte[size];int got;if(!DeviceIoControl(h,code,input,input==null?0:input.Length,data,data.Length,out got,IntPtr.Zero))throw new Win32Exception(Marshal.GetLastWin32Error());if(got<8)throw new IOException(L.Text("ext.incompleteResponse"));return data;}
  static bool Usb(SafeFileHandle h){var d=Query(h,0x2d1400,new byte[12],65536);return BitConverter.ToUInt32(d,28)==7;}
  internal static uint DiskNumber(string root){if(!System.Text.RegularExpressions.Regex.IsMatch(root??"",@"^[A-Za-z]:\\$"))throw new IOException(L.Text("ext.invalidRoot"));using(var h=CreateFile(@"\\.\"+root.Substring(0,2),0,3,IntPtr.Zero,3,0,IntPtr.Zero)){if(h.IsInvalid)throw new Win32Exception(Marshal.GetLastWin32Error());return BitConverter.ToUInt32(Query(h,0x2d1080,null,12),4);}}
  internal static ExtSource[] Devices(){return UsbStorageDevice.Enumerate().Where(x=>x.Source!=null).Select(x=>x.Source).ToArray();}
  internal static ExtSource Image(string path){path=Path.GetFullPath(path);PathSafety.RejectLinks(path);var f=new FileInfo(path);if(!f.Exists)throw new FileNotFoundException(path);return new ExtSource{Device=path,Name=f.Name,Length=f.Length,Token=f.Length+"|"+f.LastWriteTimeUtc.Ticks};}
  internal static Stream Open(ExtSource source){if(source==null)throw new IOException(L.Text("ext.missingSource"));if(!source.Physical){var now=Image(source.Device);if(now.Token!=source.Token)throw new IOException(L.Text("ext.changed"));return new FileStream(now.Device,FileMode.Open,FileAccess.Read,FileShare.Read);}var found=Devices().FirstOrDefault(x=>String.Equals(x.Device,source.Device,StringComparison.OrdinalIgnoreCase)&&x.Token==source.Token&&(source.Length<=0||x.Length<=0||x.Length==source.Length));if(found==null)throw new IOException(L.Text("ext.changed"));return new ExtDiskStream(found);}
  ExtDiskStream(ExtSource source){handle=CreateFile(source.Device,0x80000000,3,IntPtr.Zero,3,0,IntPtr.Zero);try{if(handle.IsInvalid)throw new Win32Exception(Marshal.GetLastWin32Error());if(!Usb(handle))throw new IOException(L.Text("ext.usbOnly"));length=BitConverter.ToInt64(Query(handle,0x7405c,null,8),0);sector=source.Sector;try{sector=BitConverter.ToInt32(Query(handle,0x70000,null,24),20);}catch(Win32Exception){}if((source.Length>0&&length!=source.Length)||sector<512||sector>65536||(sector&(sector-1))!=0)throw new IOException(L.Text("ext.changed"));cache=new byte[Math.Max(65536,sector)];}catch{handle.Dispose();throw;}}
  public override bool CanRead{get{return handle!=null&&!handle.IsClosed;}}public override bool CanSeek{get{return CanRead;}}public override bool CanWrite{get{return false;}}public override long Length{get{return length;}}public override long Position{get{return position;}set{if(value<0||value>length)throw new IOException(L.Text("ext.readOutsideDisk"));position=value;}}
  public override int Read(byte[] buffer,int offset,int count){if(buffer==null||offset<0||count<0||offset>buffer.Length-count)throw new ArgumentException();int total=0;while(count>0&&position<length){if(cacheStart<0||position<cacheStart||position>=cacheStart+cached){cacheStart=position/sector*sector;int request=(int)Math.Min(cache.Length,length-cacheStart);request-=request%sector;if(request==0)throw new EndOfStreamException();long at;if(!SetFilePointerEx(handle,cacheStart,out at,0)||!ReadFile(handle,cache,request,out cached,IntPtr.Zero))throw new Win32Exception(Marshal.GetLastWin32Error());if(cached<=0)throw new EndOfStreamException();}int available=Math.Min(count,cached-(int)(position-cacheStart));Buffer.BlockCopy(cache,(int)(position-cacheStart),buffer,offset,available);position+=available;offset+=available;count-=available;total+=available;}return total;}
  public override long Seek(long offset,SeekOrigin origin){Position=checked((origin==SeekOrigin.Begin?0:origin==SeekOrigin.Current?position:length)+offset);return position;}public override void Flush(){}public override void SetLength(long value){throw new NotSupportedException();}public override void Write(byte[] b,int o,int c){throw new NotSupportedException();}protected override void Dispose(bool disposing){if(handle!=null){handle.Dispose();handle=null;}base.Dispose(disposing);}
 }
 internal sealed class ExtSlice:Stream {readonly Stream source;readonly long start,length;long pos;internal ExtSlice(Stream s,long offset,long size){if(offset<0||size<0||offset>s.Length-size)throw new IOException(L.Text("ext.partitionOutsideDisk"));source=s;start=offset;length=size;}public override bool CanRead{get{return true;}}public override bool CanSeek{get{return true;}}public override bool CanWrite{get{return false;}}public override long Length{get{return length;}}public override long Position{get{return pos;}set{if(value<0||value>length)throw new IOException(L.Text("ext.readOutsidePartition"));pos=value;}}public override int Read(byte[] b,int o,int c){c=(int)Math.Min(c,length-pos);source.Position=start+pos;int n=source.Read(b,o,c);pos+=n;return n;}public override long Seek(long o,SeekOrigin k){Position=checked((k==SeekOrigin.Begin?0:k==SeekOrigin.Current?pos:length)+o);return pos;}public override void Flush(){}public override void SetLength(long l){throw new NotSupportedException();}public override void Write(byte[] b,int o,int c){throw new NotSupportedException();}}
}
